<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Falling Sand</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: radial-gradient(circle at 50% 0%, #242a38, #0d1017 68%);
    color: #e9edf5; font: 15px system-ui, sans-serif;
  }
  main { width: min(94vw, 760px); text-align: center; }
  h1 { margin: 0 0 8px; letter-spacing: .12em; font-size: 20px; }
  p { margin: 0 0 16px; color: #9da8ba; }
  canvas {
    display: block; width: min(94vw, 640px); height: min(94vw, 640px);
    margin: 0 auto 16px; background: #10151d; border: 2px solid #374155;
    image-rendering: pixelated; cursor: crosshair; touch-action: none;
    box-shadow: 0 16px 50px #0009;
  }
  .controls { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
  button {
    border: 1px solid #46516a; border-radius: 8px; color: #eef3ff;
    background: #202838; padding: 9px 13px; cursor: pointer;
    font: inherit; transition: transform .12s, background .12s;
  }
  button:hover { background: #303b52; transform: translateY(-1px); }
  button.active { outline: 2px solid #f5f7ff; background: #46516a; }
  #mat-sand { border-color: #d5af57; } #mat-water { border-color: #4c9dff; }
  #mat-wall { border-color: #9299a6; } #mat-acid { border-color: #75df63; }
  #mat-empty { border-color: #303846; } #clear { border-color: #d85e68; }
</style>
</head>
<body>
<main>
  <h1>FALLING SAND</h1>
  <p>Choose a material and drag across the sandbox.</p>
  <canvas id="sand" width="120" height="120" aria-label="Falling sand simulation"></canvas>
  <div class="controls">
    <button id="mat-sand" class="active">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
</main>
<script>
(() => {
  const canvas = document.getElementById("sand"), ctx = canvas.getContext("2d");
  const w = 120, h = 120, EMPTY = 0, SAND = 1, WATER = 2, WALL = 3, ACID = 4;
  const names = ["empty", "sand", "water", "wall", "acid"];
  const ids = { empty: EMPTY, sand: SAND, water: WATER, wall: WALL, acid: ACID };
  const colors = ["#10151d", "#dcb85c", "#4199e8", "#747d8d", "#75dc5e"];
  const grid = new Uint8Array(w * h);
  let selected = SAND, seed = 0x13579bdf, drawing = false;

  const at = (x, y) => grid[y * w + x];
  const put = (x, y, v) => { grid[y * w + x] = v; };
  const random = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) & 1);

  function move(x, y, nx, ny, moved) {
    put(nx, ny, at(x, y)); put(x, y, EMPTY);
    moved[ny * w + nx] = 1;
  }

  function displaceLiquid(x, y, liquid, moved) {
    const order = random() ? [-1, 1] : [1, -1];
    for (const d of order) {
      const sx = x + d;
      if (sx > 0 && sx < w - 1 && at(sx, y) === EMPTY) {
        put(sx, y, liquid);
        put(x, y, EMPTY);
        moved[y * w + sx] = 1;
        return true;
      }
    }
    return false;
  }

  function step() {
    const moved = new Uint8Array(w * h);
    for (let y = h - 2; y >= 0; y--) {
      for (let x = 1; x < w - 1; x++) {
        const i = y * w + x, type = grid[i];
        if (moved[i] || type === EMPTY || type === WALL) continue;
        const below = at(x, y + 1);

        if (type === ACID) {
          if (below === SAND || below === WALL) put(x, y + 1, EMPTY);
          const dirs = random() ? [-1, 1] : [1, -1];
          for (const d of dirs) {
            const side = at(x + d, y);
            if (side === SAND || side === WALL) { put(x + d, y, EMPTY); break; }
          }
        }

        const currentBelow = at(x, y + 1);
        if (currentBelow === EMPTY) {
          move(x, y, x, y + 1, moved);
          continue;
        }

        if (type === SAND && (currentBelow === WATER || currentBelow === ACID)) {
          if (displaceLiquid(x, y, currentBelow, moved)) {
            put(x, y + 1, SAND);
            moved[(y + 1) * w + x] = 1;
            continue;
          }
        }

        const dirs = random() ? [-1, 1] : [1, -1];
        let acted = false;
        if (type === SAND) {
          for (const d of dirs) {
            if (at(x + d, y + 1) === EMPTY) {
              move(x, y, x + d, y + 1, moved); acted = true; break;
            }
          }
        } else {
          for (const d of dirs) {
            if (at(x + d, y + 1) === EMPTY) {
              move(x, y, x + d, y + 1, moved); acted = true; break;
            }
          }
          if (!acted) {
            for (const d of dirs) {
              if (at(x + d, y) === EMPTY) {
                move(x, y, x + d, y, moved); break;
              }
            }
          }
        }
      }
    }
  }

  function render() {
    const image = ctx.createImageData(w, h), data = image.data;
    for (let i = 0; i < grid.length; i++) {
      const hex = colors[grid[i]], n = parseInt(hex.slice(1), 16);
      data[i * 4] = n >> 16; data[i * 4 + 1] = (n >> 8) & 255;
      data[i * 4 + 2] = n & 255; data[i * 4 + 3] = 255;
    }
    ctx.putImageData(image, 0, 0);
  }

  function tick(n = 1) {
    n = Math.max(0, Math.floor(Number(n) || 0));
    for (let i = 0; i < n; i++) step();
    render();
  }

  function clear() { grid.fill(EMPTY); render(); }

  window.sim = {
    w, h,
    tick,
    get(x, y) {
      return (Number.isInteger(x) && Number.isInteger(y) && x >= 0 && x < w && y >= 0 && y < h)
        ? names[at(x, y)] : "empty";
    },
    set(x, y, material) {
      if (Number.isInteger(x) && Number.isInteger(y) && x >= 0 && x < w && y >= 0 && y < h && ids[material] !== undefined) {
        put(x, y, ids[material]); render();
      }
    },
    clear
  };

  function paint(e) {
    const r = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - r.left) * w / r.width);
    const y = Math.floor((e.clientY - r.top) * h / r.height);
    const radius = selected === WALL ? 1 : 2;
    for (let dy = -radius; dy <= radius; dy++) for (let dx = -radius; dx <= radius; dx++) {
      if (dx * dx + dy * dy <= radius * radius) {
        const px = x + dx, py = y + dy;
        if (px > 0 && px < w - 1 && py >= 0 && py < h - 1) put(px, py, selected);
      }
    }
    render();
  }

  canvas.addEventListener("pointerdown", e => { drawing = true; canvas.setPointerCapture(e.pointerId); paint(e); });
  canvas.addEventListener("pointermove", e => { if (drawing) paint(e); });
  canvas.addEventListener("pointerup", () => drawing = false);
  canvas.addEventListener("pointercancel", () => drawing = false);

  for (const name of Object.keys(ids)) {
    document.getElementById("mat-" + name).onclick = () => {
      selected = ids[name];
      document.querySelectorAll(".controls button").forEach(b => b.classList.remove("active"));
      document.getElementById("mat-" + name).classList.add("active");
    };
  }
  document.getElementById("clear").onclick = clear;

  let last = 0;
  function animate(t) {
    if (t - last > 33) { tick(1); last = t; }
    requestAnimationFrame(animate);
  }
  render();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
